class Solution {
    public int maxEqualRowsAfterFlips(int[][] matrix){
        Map<String,Integer> frequency=new HashMap<>();
        int answer=0;
        for(int[] row:matrix){
            StringBuilder key=new StringBuilder();
            for(int bit:row)key.append(bit^row[0]);
            int count=frequency.merge(key.toString(),1,Integer::sum);
            answer=Math.max(answer,count);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxEqualRowsAfterFlips(matrix:Array<IntArray>):Int{
        val frequency=mutableMapOf<String,Int>();
        var answer=0;
        for(row in matrix){
            val key=row.joinToString(""){
                (it xor row[0]).toString()
            };
            val count=(frequency[key]?:0)+1;
            frequency[key]=count;
            answer=maxOf(answer,count)
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int maxEqualRowsAfterFlips(vector<vector<int>>& matrix){
        unordered_map<string,int> frequency;
        int answer=0;
        for(auto& row:matrix){
            string key;
            for(int bit:row)key+=char('0'+(bit^row[0]));
            answer=max(answer,++frequency[key]);
        }
        return answer;
    }
};
